import sys
from collections import defaultdict, deque

MOD = 10**9 + 7

def dfs(node, parent, graph, dp):
    dp[node][0] = 0
    dp[node][1] = 0
    max_child_dist = [0, 0]

    for neighbor in graph[node]:
        if neighbor != parent:
            dfs(neighbor, node, graph, dp)
            for i in range(2):
                dp[node][i] += dp[neighbor][i]
                if dp[node][i] > max_child_dist[i]:
                    max_child_dist[i], dp[node][i] = dp[node][i], max_child_dist[i]

    dp[node][0] += max_child_dist[0]
    dp[node][1] += max_child_dist[1]

def solve():
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    edges = [(int(data[2*i+1]), int(data[2*i+2])) for i in range(N-1)]

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    dp = [[0, 0] for _ in range(N+1)]

    dfs(1, -1, graph, dp)

    total_niceness = 0

    def calculate_niceness(dp_node):
        return max(max(dp_node), 0)

    def update_dp(parent, child, dp_parent, dp_child):
        dp_parent[0] -= dp_child[0]
        dp_parent[1] -= dp_child[1]

        new_max_child_dist = [0, 0]
        for i in range(2):
            dp_parent[i] += dp_child[i]
            if dp_parent[i] > new_max_child_dist[i]:
                new_max_child_dist[i], dp_parent[i] = dp_parent[i], new_max_child_dist[i]

        dp_parent[0] += new_max_child_dist[0]
        dp_parent[1] += new_max_child_dist[1]

    stack = [(1, -1)]
    while stack:
        node, parent = stack.pop()
        total_niceness += calculate_niceness(dp[node])

        for neighbor in graph[node]:
            if neighbor != parent:
                update_dp(dp[parent], dp[neighbor], dp[parent], dp[neighbor])
                stack.append((neighbor, node))

    print(total_niceness % MOD)

