    solve()

import sys
from collections import defaultdict, deque

MOD = 10**9 + 7

def dfs(node, parent, color, dists, dp):
    max_white = 0
    max_black = 0

    for neighbor, edge_id in adj[node]:
        if neighbor == parent:
            continue

        if color & (1 << edge_id):
            max_white = max(max_white, dists[neighbor][0] + 1)
        else:
            max_black = max(max_black, dists[neighbor][1] + 1)

    dp[node][color] = (max_white, max_black)

    for neighbor, edge_id in adj[node]:
        if neighbor == parent:
            continue

        new_color = color ^ (1 << edge_id)

        if color & (1 << edge_id):
            dists[neighbor][0] = max(dists[neighbor][0], dists[node][0] + 1)
        else:
            dists[neighbor][1] = max(dists[neighbor][1], dists[node][1] + 1)

        dfs(neighbor, node, new_color, dists, dp)

def main():
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    edges = [(int(data[i*2+1]) - 1, int(data[i*2+2]) - 1) for i in range(N-1)]

    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append((v, len(adj[u])))
        adj[v].append((u, len(adj[v])-1))

    dp = [[None] * (1 << (N-1)) for _ in range(N)]
    dists = [[0, 0] for _ in range(N)]

    dfs(0, -1, 0, dists, dp)
    dfs(0, -1, 1, dists, dp)

    total_niceness = 0

    for color in range(1 << (N-1)):
        max_white = 0
        max_black = 0

        for node in range(N):
            if color & (1 << node):
                max_white = max(max_white, dp[node][color][0])
            else:
                max_black = max(max_black, dp[node][color][1])

        total_niceness += max(max_white, max_black)

    print(total_niceness % MOD)

if __name__ == "__main__":
    main()
